@php
    $isGlobal = $isGlobal ?? false;
    $isEditing = $question->exists;
    $wizardOptions = $question->options?->map(fn ($option): array => [
        'text' => $option->option_text,
        'correct' => $option->is_correct,
        'imageUrl' => $option->image_path ? \Illuminate\Support\Facades\Storage::disk('public')->url($option->image_path) : null,
    ])->values() ?? collect();
    if ($wizardOptions->isEmpty()) {
        $wizardOptions = collect([['text' => '', 'correct' => false, 'imageUrl' => null], ['text' => '', 'correct' => false, 'imageUrl' => null]]);
    }
    $selectedCorrectOption = $wizardOptions->search(fn (array $option): bool => $option['correct'] === true);
    $questionImageUrl = $question->question_image_path ? \Illuminate\Support\Facades\Storage::disk('public')->url($question->question_image_path) : null;
    $correctAnswerImageUrl = $question->correct_answer_image_path ? \Illuminate\Support\Facades\Storage::disk('public')->url($question->correct_answer_image_path) : null;
