<script>
    window.questionWizard = function (initial) { return { ...initial, step: 1, addOption() { if (this.options.length < 4) { this.options.push(''); this.optionImages.push(null); } }, removeOption(index) { if (this.options.length > 2) { this.options.splice(index, 1); this.optionImages.splice(index, 1); if (this.correctOption >= this.options.length) this.correctOption = this.options.length - 1; } }, insertMarker(field, marker) { const input = this.$refs[field]; const start = input.selectionStart; const end = input.selectionEnd; const value = this[field] || ''; const token = marker === 'Bold' ? '**' : marker === 'Italic' ? '_' : marker === 'Underline' ? '__' : ''; if (!token) return; this[field] = value.slice(0, start) + token + value.slice(start, end) + token + value.slice(end); this.$nextTick(() => { input.focus(); input.setSelectionRange(start + token.length, end + token.length); }); } }; };
</script>
